      pageId, isSearch, isDoc: !isSearch, isMobile, isDesktop: !isMobile,
      titleRuns: parse(P.titleRuns, go, false), navTitle: P.navTitle, hasSection: !!P.section, sectionName: P.section || '',
      man: P.man, manName: P.manName, synopsis: P.synopsis.map((t) => ({ t })),
      blocks, nav, tabs, prev: link(P.prev), next: link(P.next), hasPrev: !!P.prev, hasNext: !!P.next,
